mapper.select:
SELECT id, credential_id AS credentialId, symbol, cycle_key AS positionCycleKey, position_side AS positionSide, direction, opening_quantity AS openingQuantity, closing_quantity AS closingQuantity, remaining_quantity AS remainingQuantity, opening_notional AS openingNotional, closing_notional AS closingNotional, realized_pnl AS realizedPnl, opening_fill_count AS openingFillCount, closing_fill_count AS closingFillCount, leverage_snapshot AS leverage, price_tick_size_snapshot AS priceTickSizeSnapshot, opening_balance AS openingBalance, opening_balance_at AS openingBalanceAt, closing_balance AS closingBalance, closing_balance_at AS closingBalanceAt, opened_at AS openedAt, closed_at AS closedAt, status, baseline_unknown AS baselineUnknown FROM quant_position_cycle WHERE credential_id IN
#{credentialId}
AND symbol=#{symbol} AND opened_at IS NOT NULL AND opened_at>=#{fromUtc} AND opened_at IS NOT NULL AND opened_at<#{toUtc} ORDER BY COALESCE(opened_at,created_at) DESC,id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM quant_position_cycle
WHERE credential_id IN

    #{credentialId}

AND symbol=#{symbol}
AND opened_at IS NOT NULL AND opened_at>=#{fromUtc}
AND opened_at IS NOT NULL AND opened_at<#{toUtc}

SELECT COUNT(DISTINCT CONCAT(credential_id,':',symbol))
FROM quant_position_cycle_state
WHERE credential_id IN

    #{credentialId}

  AND (status<>'READY' OR incomplete=1)
AND symbol=#{symbol}

mapper.delete:
DELETE FROM quant_trade_cycle_allocation
WHERE position_cycle_id IN (
    SELECT id FROM quant_position_cycle
    WHERE credential_id=#{credentialId} AND symbol=#{symbol} AND position_side=#{positionSide}
)

mapper.select:
SELECT position_cycle_id AS cycleId, allocation_role AS allocationRole, exchange_order_id AS exchangeOrderId, exchange_trade_id AS exchangeTradeId FROM quant_trade_cycle_allocation WHERE position_cycle_id IN
#{cycleId}
ORDER BY position_cycle_id,trade_time,exchange_trade_id

SELECT position_cycle_id AS cycleId, COALESCE(NULLIF(UPPER(TRIM(commission_asset)),''),'UNKNOWN') AS commissionAsset, SUM(commission) AS commission FROM quant_trade_cycle_allocation WHERE position_cycle_id IN
#{cycleId}
GROUP BY position_cycle_id,COALESCE(NULLIF(UPPER(TRIM(commission_asset)),''),'UNKNOWN') ORDER BY position_cycle_id,commissionAsset

